// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy, Bank} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    function setUp() public { c = new ModifierEntrancy(); }
    function testFuzz_property(uint256 seedBalance, address actor) public {
        vm.assume(actor != address(0));
        seedBalance = bound(seedBalance, 1, type(uint128).max);

        // The fuzzer cannot synthesise an external Bank-like msg.sender, so we make `actor`
        // able to pass the supportsToken check by calling from a deployed Bank address.
        Bank bank = new Bank();
        vm.prank(address(bank));
        // First airdrop gives the bank address a nonzero balance (hasNoBalance holds when zero).
        c.airDrop();

        // Now the same account already has a nonzero balance. On the reference a second call
        // must revert because hasNoBalance fails; on the mutant it succeeds.
        uint256 before = c.tokenBalance(address(bank));
        vm.prank(address(bank));
        bool ok = true;
        try c.airDrop() { ok = true; } catch { ok = false; }
        uint256 afterBal = c.tokenBalance(address(bank));

        assertTrue(!ok && afterBal == before);
    }
}
